{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C39"],
      "claim": "Testosterone undecanoate, a long-chain ester prodrug, has a mean absolute oral bioavailability of 6.8 ± 3.3% in humans, supporting low F for lipophilic long-chain esters.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "Dimethandrolone undecanoate, another long-chain undecanoate ester, shows poor and inconsistent oral bioavailability in men.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C60"],
      "claim": "Colesevelam, a non-absorbed GI-acting drug, has oral bioavailability <0.04%, illustrating negligible systemic absorption for locally acting oral agents.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Tetrabenazine has very low oral systemic availability (mean 0.049 ± 0.032) in patients, demonstrating that lipophilic drugs with extensive first-pass metabolism can fall far below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Nimodipine, a lipophilic drug with extensive first-pass metabolism, has a mean oral bioavailability of 15.9% with most individual values below 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Low: orlistat is a minimally absorbed GI lipase inhibitor; all transferable evidence and known behavior place its oral F well below 20%.",
  "evidence_gaps": [
    "No direct orlistat bioavailability record in the provided set; extrapolation relies on long-chain ester and non-absorbed GI drug analogs.",
    "No IV-oral comparison for the query molecule itself.",
    "Human F data for analogs vary with formulation and food, but all remain below 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

